import {captureCachedBossEmission} from './boss-emission-materials.js';
import {captureSceneryEmission} from './scenery-emission-bridge.js';
import {creatureBuilder,paintCreatureMesh} from './dungeon-creature-mesh.js';
import {micelialCurve,micelialAngle,micelialDirection,micelialReverseWarning,micelialGapAt,sporePoint} from './micelial-mechanic.js';
export const MICELIAL_MATERIALS=Object.freeze({cap:['#f27f72','#ce2029','#591d35'],bone:['#ffffe0','#c4ccc7','#8394a6'],dark:['#5c627d','#374252','#161928'],spore:['#a2e66f','#5dae27','#1d3926'],gold:['#ffd95a','#e97c07','#9c3824']});
const {cap:C,bone:B,dark:D,spore:S,gold:G}=MICELIAL_MATERIALS,tau=Math.PI*2,clamp=x=>Math.max(0,Math.min(1,x));
function volume(m,id,rings,ramp,transform=p=>p,segments=12){const rings3=rings.map(([radius,z,flatten=1])=>Array.from({length:segments},(_,i)=>{const a=tau*i/segments;return[Math.cos(a)*radius,Math.sin(a)*radius*flatten,z];}));for(let j=0;j<rings3.length-1;j++)for(let i=0;i<segments;i++){const k=(i+1)%segments;m.face(id+'-'+j+'-'+i,[rings3[j][i],rings3[j][k],rings3[j+1][k],rings3[j+1][i]],ramp,transform);}m.face(id+'-top',rings3.at(-1),ramp,transform);m.face(id+'-bottom',[...rings3[0]].reverse(),ramp,transform);}
// Key poses are measured in musical pulses. The shadow and ground pivot stay fixed.
export function elasticReaction(beat,hitAt,soft=false){const t=beat-hitAt;if(t<0||t>=1.15)return 0;let a;if(t<.16)a=Math.sin(t/.16*Math.PI/2);else if(t<.34)a=1-(t-.16)/.18*.65;else if(t<.60)a=.35-(t-.34)/.26*.49;else a=-.14*(1-(t-.60)/.55);return a*(soft?.4:1);}
export const micelialVisualOffset=b=>-5.5*((b.arenaSize?.rows??15)-2)/13;
export function micelialMesh({beat=0,hitAt=-100,breakAt=-100,nextRelease=8,soft=false,includeHidden=false}={}){const m=creatureBuilder({soft:true,includeHidden}),recoil=beat-hitAt,hit=recoil>=0&&recoil<1.5?Math.sin(recoil*13)*Math.exp(-recoil*3)*.08:0,prepare=beat>=nextRelease-2&&beat<nextRelease?Math.sin((beat-(nextRelease-2))/2*Math.PI/2):0,sway=soft?0:Math.sin(beat*Math.PI/2)*.025,angle=sway+hit,hurt=elasticReaction(beat,breakAt,soft),squash=1-.24*hurt,wide=1+.13*hurt;
 const stem=p=>{const u=clamp(p[2]/44);return[p[0]*(1+.18*hurt*u)+angle*10*u,p[1]*(1+.1*hurt*u),p[2]*squash-prepare*1.6*u];},cap=p=>{const z=p[2]-43;return[(p[0]*Math.cos(angle)-z*Math.sin(angle))*wide+angle*10,(p[1]*Math.cos(hurt*.16)-z*Math.sin(hurt*.16))*wide,43*squash+p[0]*Math.sin(angle)+(z*Math.cos(angle)*Math.cos(hurt*.16)+p[1]*Math.sin(hurt*.16))*(1-.1*hurt)-prepare*2];};
 for(const side of [-1,1])m.box('root-'+side,side*12,6,0,22,19,7,B,1.2,stem);
 volume(m,'stem',[[12,4,.8],[13,8,.8],[10,30,.85],[15,43,.8]],B,stem,10);
 for(const side of [-1,1])m.box('branch-'+side,side*18,1,21,19,13,10,B,2.2,stem);
 // A distinct ivory underside, narrow rim, and broad red crown keep the identity.
 volume(m,'cap-underside',[[23,40,.70],[36,44,.70],[39,47,.70]],B,cap,16);
 volume(m,'cap',[[39,47,.70],[39,50,.70],[34,59,.70],[23,65,.70],[9,67,.70]],C,cap,16);
 // Ivory inlays lie on the exact planar cap panels. No buried or floating plates.
 for(const [id,sector,u0,u1]of [['left',6,.18,.78],['right',1,.15,.82],['back',10,.22,.78]]){const a=sector*tau/16,z=(sector+1)*tau/16,point=(r,u)=>[(Math.cos(a)*(1-u)+Math.cos(z)*u)*r,(Math.sin(a)*(1-u)+Math.sin(z)*u)*r*.70,65-(r-23)*6/11+.18];m.face('spot-'+id,[point(24,u0),point(31,u0),point(31,u1),point(24,u1)],B,cap);}
 m.box('spot-center',0,0,67.15,11,8,.4,B,.12,cap);
 // Small eyes follow the actual front stem plane and share its pivot.
 const anger=clamp(hurt*2),ink=[D[2],D[2],D[2]];for(const side of [-1,1])m.box('eye-'+side,side*4.6,9.1,27-4*anger,3.2,1.1,5.5,ink,.35,stem);
 if(anger>.05)for(const side of[-1,1])m.box('angry-brow-'+side,side*4.6,9.8,33.4-6*anger,5.8,1.4,1.4*anger,ink,.12,p=>stem([p[0],p[1],p[2]+(p[0]-side*4.6)*side*.5*anger]));
 for(const f of m.faces)if(f.id.startsWith('spot-'))f.depth+=12;
 return m.finish();}
const cache=new Map();export const micelialCacheSize=()=>cache.size;
export function paintMicelial(c,b,x,y,beat,soft){const sample=Math.floor(beat*20)/20,m=b.mycelium,key=[sample,m.hitAt,m.breakAt,m.nextRelease,soft].join(':');y+=micelialVisualOffset(b);const hurt=elasticReaction(beat,m.breakAt,soft);c.save();c.globalCompositeOperation='screen';const light=c.createRadialGradient(x,y-64+hurt*11,15,x,y-64+hurt*11,57);light.addColorStop(0,C[1]+'44');light.addColorStop(.65,C[1]+'20');light.addColorStop(1,C[1]+'00');c.globalAlpha=soft?.65:.65+.12*Math.sin(beat*Math.PI*2)+Math.max(0,hurt)*.3;c.fillStyle=light;c.fillRect(x-58,y-123+hurt*11,116,116);c.restore();let image=cache.get(key);if(!image){image=new OffscreenCanvas(396,360);const g=image.getContext('2d');g.scale(3,3);paintCreatureMesh(g,micelialMesh({beat:sample,hitAt:m.hitAt,breakAt:m.breakAt,nextRelease:m.nextRelease,soft}),66,99,1.24,{shadow:true,emissionIndex:4});if(cache.size>=40){const first=cache.keys().next().value;cache.get(first).width=1;cache.delete(first);}cache.set(key,image);}c.drawImage(image,x-66,y-99,132,120);captureCachedBossEmission(c,image,x-66,y-99,132,120,x,y);}
export function nucleusMesh({beat=0,hitAt=-100,id=0,soft=false,includeHidden=false}={}){const m=creatureBuilder({soft:true,includeHidden}),hurt=elasticReaction(beat,hitAt,soft),pulse=soft?0:Math.sin(beat*Math.PI*2+id)*.35,deform=p=>[p[0]*(1+.24*hurt),p[1]*(1+.18*hurt),p[2]*(1-.34*hurt)],capDeform=p=>[p[0]*(1+.24*hurt),(p[1]*Math.cos(hurt*.16)-(p[2]-9)*Math.sin(hurt*.16))*(1+.18*hurt),p[2]*(1-.34*hurt)+p[1]*Math.sin(hurt*.16)];volume(m,'nucleus-foot',[[6,0,.8],[6.5,2,.8],[5,9,.8]],B,deform);volume(m,'nucleus-rim',[[7,8,.73],[11,10,.73],[11.4,11,.73]],B,capDeform);volume(m,'nucleus-cap',[[11.4,11,.73],[11.4,13+pulse,.73],[9,18+pulse,.73],[4,20+pulse,.73]],S,capDeform);m.box('nucleus-spot',-2,-1,20.2+pulse,4,3,.4,B,.1,capDeform);for(const side of[-1,1])m.box('nucleus-eye-'+side,side*2,4.1,5.5,1.6,1,2.4,[D[2],D[2],D[2]],.15,deform);for(const f of m.faces)if(f.id==='nucleus-spot')f.depth+=5;return m.finish();}
export function paintMicelialNucleus(c,n,x,y,beat,soft){const faces=nucleusMesh({beat,hitAt:n.micelialHitAt??-100,id:n.id,soft});paintCreatureMesh(c,faces,x,y,1.1,{shadow:true});captureSceneryEmission(c,'nucleus',{faces,x,y,scale:1.1});c.save();c.fillStyle=D[2];c.fillRect(x-9,y+5,18,3);c.fillStyle=S[0];c.fillRect(x-9,y+5,18*n.hp/n.maxHp,1.5);c.restore();}
function path(c,points,project){c.beginPath();points.forEach((p,i)=>{const v=project(p.x,p.y);i?c.lineTo(v.x/2,v.y/2):c.moveTo(v.x/2,v.y/2);});}
function drawSpiral(c,b,beat,project,color,width,alpha){const points=micelialCurve(b,beat),radius=width/6*.38;c.save();c.fillStyle=color;c.globalAlpha=alpha;for(let i=1;i<points.length;i++){const a=points[i-1],z=points[i];if(micelialGapAt(b,a,beat)||micelialGapAt(b,z,beat))continue;const dx=z.x-a.x,dy=z.y-a.y,n=Math.hypot(dx,dy),nx=-dy/n*radius,ny=dx/n*radius;path(c,[{x:a.x+nx,y:a.y+ny},{x:z.x+nx,y:z.y+ny},{x:z.x-nx,y:z.y-ny},{x:a.x-nx,y:a.y-ny}],project);c.closePath();c.fill();}c.restore();}
export function paintMicelialGround(c,b,beat,project,soft){if(beat<2)return;const m=b.mycelium,active=beat>=4,warning=micelialReverseWarning(beat),color=warning?G:S,pulse=soft?.4:Math.pow(1-beat%1,2);
 // The faint swept ribbon shows precisely the interval judged at the next pulse.
 if(active){for(let u=0;u<=1;u+=.2)drawSpiral(c,b,Math.ceil(beat)-u,project,color[1],6,.06);drawSpiral(c,b,beat,project,color[2],10,.78);drawSpiral(c,b,beat,project,color[1],6,.95);drawSpiral(c,b,beat,project,color[0],1.5,.8);}
 else{c.save();c.setLineDash([4,6]);drawSpiral(c,b,4,project,S[0],3,.5);c.restore();}
 const curve=micelialCurve(b,Math.max(4,beat));c.save();for(let i=5;i<curve.length;i+=8){const p=curve[i];if(micelialGapAt(b,p,beat))continue;const v=project(p.x,p.y);c.fillStyle=color[0];c.globalAlpha=.7+pulse*.3;c.beginPath();c.moveTo(v.x/2-2,v.y/2-4);c.lineTo(v.x/2+2,v.y/2-4);c.lineTo(v.x/2,v.y/2-8);c.closePath();c.fill();}c.restore();
 if(warning){const p=project(b.x,b.y);c.save();c.strokeStyle=G[0];c.lineWidth=2.2;c.beginPath();const a=micelialAngle(b,beat);c.ellipse(p.x/2,p.y/2,23,10,0,a,a+micelialDirection(beat)*2);c.stroke();c.restore();}
 const prep=beat>=m.nextRelease-2&&beat<m.nextRelease;if(prep){c.save();const a=micelialAngle(b,m.nextRelease)+Math.PI/2;c.setLineDash([3,4]);c.strokeStyle=S[0];c.globalAlpha=.3+pulse*.4;c.lineWidth=1;for(const side of [0,1]){const from=project(b.x+Math.cos(a+side*Math.PI)*2,b.y+Math.sin(a+side*Math.PI)*2),to=project(b.x+Math.cos(a+side*Math.PI)*6,b.y+Math.sin(a+side*Math.PI)*6);c.beginPath();c.moveTo(from.x/2,from.y/2);c.lineTo(to.x/2,to.y/2);c.stroke();}c.restore();}
 for(const s of m.spores){if(beat<s.born||beat>=s.until)continue;const p=sporePoint(b,s,beat),v=project(p.x,p.y),last=sporePoint(b,s,Math.max(s.born,beat-.3)),q=project(last.x,last.y);c.save();c.strokeStyle=S[1];c.globalAlpha=.6;c.lineWidth=6;c.beginPath();c.moveTo(q.x/2,q.y/2-5);c.lineTo(v.x/2,v.y/2-5);c.stroke();c.fillStyle=S[1];c.globalAlpha=.24;c.beginPath();c.ellipse(v.x/2,v.y/2,14,10,0,0,tau);c.fill();c.fillStyle=D[2];c.globalAlpha=.6;c.beginPath();c.ellipse(v.x/2,v.y/2,5,2.5,0,0,tau);c.fill();c.globalAlpha=1;c.fillStyle=S[2];c.beginPath();c.arc(v.x/2,v.y/2-6,5.5,0,tau);c.fill();c.fillStyle=S[1];c.beginPath();c.arc(v.x/2-1,v.y/2-7,4,0,tau);c.fill();c.fillStyle=S[0];c.fillRect(v.x/2-3,v.y/2-10,2,2);c.restore();}
 for(const g of m.gaps){const p=project(g.x,g.y),age=beat-g.born;if(age<0)continue;c.save();c.globalAlpha=clamp(1-age/2);c.strokeStyle=B[0];c.lineWidth=1.5;c.beginPath();c.ellipse(p.x/2,p.y/2,12+age*9,6+age*3,0,0,tau);c.stroke();if(age<1){const goal=project(b.x,b.y);c.fillStyle=S[0];for(let i=0;i<5;i++){const u=clamp(age*1.4-i*.07);c.fillRect(p.x/2+(goal.x-p.x)/2*u,p.y/2+(goal.y-p.y)/2*u-18*Math.sin(u*Math.PI)-u*17,2,2);}}c.restore();}}

